"""Heat generated by the heat pump: by day, week, month and year, and a prediction for the
whole year.

There is no heat meter. Each day's heat is the estimate the SCOP figures already make (hot
water from the cylinder's temperature rise, heating from the flow and outdoor temperatures),
so these totals are estimates too.

The prediction fits each day's heat to how cold it was: heat = hot water + k × degree days,
where degree days are how far the day's average fell below the base (15.5 °C). Days of this
year that have a heat figure count as they are; every other day of the year is predicted
from the fit, with the outdoor temperature it had (days already past), the same date's
temperature in an earlier year, or failing that a typical southern England month.
"""

from __future__ import annotations

import math
from datetime import date, timedelta

from . import heating

# Typical daily mean temperatures by month for southern England (Met Office 1991-2020
# averages, rounded); only used for days with no reading this year or in earlier years.
TYPICAL_C = {
    1: 5.0,
    2: 5.3,
    3: 7.2,
    4: 9.4,
    5: 12.6,
    6: 15.6,
    7: 17.7,
    8: 17.5,
    9: 15.0,
    10: 11.6,
    11: 7.9,
    12: 5.4,
}
MIN_FIT_DAYS = 14  # days with heat and temperature needed for a prediction
MIN_FIT_DEGREE_DAYS = 3.0  # spread of degree days needed to fit the heating part
RECENT_DAYS = 31
RECENT_WEEKS = 13


def _as_date(value) -> date:
    return value if isinstance(value, date) else date.fromisoformat(value)


def _total(members: list[dict]) -> dict:
    water = sum(m["hot_water_heat_kwh"] for m in members)
    heat = sum(m["heating_heat_kwh"] for m in members)
    electricity = sum(m["hot_water_kwh"] + m["heating_kwh"] + m["other_kwh"] for m in members)
    total = water + heat
    return {
        "days": len(members),
        "heat_kwh": round(total, 1),
        "hot_water_heat_kwh": round(water, 1),
        "heating_heat_kwh": round(heat, 1),
        "electricity_kwh": round(electricity, 1),
        "cop": round(total / electricity, 2) if electricity >= 1 else None,
    }


def _grouped(days: list[dict], key) -> list[dict]:
    groups: dict[str, list[dict]] = {}
    for item in days:
        groups.setdefault(key(item["day"]), []).append(item)
    return [{"name": name, **_total(members)} for name, members in sorted(groups.items())]


def fit(points: list[tuple[float, float]]) -> dict | None:
    """Least squares heat = base + k × degree days, over (degree days, heat) points, with
    the parameters' covariance for a range on the prediction. None with too few days."""
    n = len(points)
    if n < MIN_FIT_DAYS:
        return None
    mean_x = sum(x for x, _ in points) / n
    mean_y = sum(y for _, y in points) / n
    sxx = sum((x - mean_x) ** 2 for x, _ in points)
    if sxx < MIN_FIT_DEGREE_DAYS**2:
        # Hardly any heating weather yet: no slope to fit. Only the hot water is known,
        # and the heating can't be predicted, so no prediction.
        return None
    slope = max(0.0, sum((x - mean_x) * (y - mean_y) for x, y in points) / sxx)
    intercept = max(0.0, mean_y - slope * mean_x)
    residuals = [y - (intercept + slope * x) for x, y in points]
    sigma2 = sum(r * r for r in residuals) / max(1, n - 2)
    return {
        "base_kwh": intercept,
        "per_degree_day_kwh": slope,
        "sigma2": sigma2,
        # Covariance of (intercept, slope).
        "var_slope": sigma2 / sxx,
        "var_intercept": sigma2 * (1 / n + mean_x**2 / sxx),
        "cov": -mean_x * sigma2 / sxx,
        "days": n,
    }


def _temperature_for(day: date, temperature: dict[date, float]) -> tuple[float, str]:
    """A day's average outdoor temperature: read, the same date in an earlier year, or typical."""
    if day in temperature:
        return temperature[day], "read"
    for back in (1, 2, 3):
        try:
            earlier = day.replace(year=day.year - back)
        except ValueError:  # 29 February
            earlier = day.replace(year=day.year - back, day=28)
        if earlier in temperature:
            return temperature[earlier], "earlier year"
    return TYPICAL_C[day.month], "typical"


def predict_year(
    year: int,
    actual: dict[date, dict],
    temperature: dict[date, float],
    model: dict,
    base_c: float,
) -> dict:
    """The year's heat: days with a figure as they are, the rest from the fit."""
    first, last = date(year, 1, 1), date(year, 12, 31)
    known = sum(
        row["hot_water_heat_kwh"] + row["heating_heat_kwh"]
        for day, row in actual.items()
        if first <= day <= last
    )
    predicted, count, degree_days = 0.0, 0, 0.0
    sources = {"read": 0, "earlier year": 0, "typical": 0}
    day = first
    while day <= last:
        if day not in actual:
            outside, source = _temperature_for(day, temperature)
            dd = max(0.0, base_c - outside)
            predicted += model["base_kwh"] + model["per_degree_day_kwh"] * dd
            degree_days += dd
            count += 1
            sources[source] += 1
        day += timedelta(days=1)
    # A rough 95% range: the uncertainty in the fit, and day-to-day scatter.
    variance = (
        count**2 * model["var_intercept"]
        + degree_days**2 * model["var_slope"]
        + 2 * count * degree_days * model["cov"]
        + count * model["sigma2"]
    )
    spread = 1.96 * math.sqrt(max(0.0, variance))
    total = known + predicted
    return {
        "year": year,
        "heat_kwh": round(total),
        "low_kwh": round(max(known, total - spread)),
        "high_kwh": round(total + spread),
        "so_far_kwh": round(known),
        "known_days": sum(1 for d in actual if first <= d <= last),
        "predicted_days": count,
        "predicted_kwh": round(predicted),
        "temperature_sources": sources,
        "hot_water_kwh_a_day": round(model["base_kwh"], 1),
        "per_degree_day_kwh": round(model["per_degree_day_kwh"], 2),
        "fit_days": model["days"],
    }


def summary(
    daily: list[dict],
    temperature: dict[date, float],
    today: date,
    base_c: float = heating.BASE_C,
    whole_years: list[dict] | None = None,
) -> dict:
    """Heat generated by day, week, month and year, and the predicted total for this year.

    `daily` is the SCOP estimate's daily figures (whole days, the last 400 or so); `today`
    is the current day. `whole_years` are the estimate's figures by year, over every day,
    used for the yearly totals as `daily` may not reach back far enough.
    """
    days = sorted(
        ({**item, "day": _as_date(item["day"])} for item in daily if _as_date(item["day"]) < today),
        key=lambda item: item["day"],
    )
    if not days:
        return {"has_data": False}
    by_day = {item["day"]: item for item in days}
    yesterday = today - timedelta(days=1)
    this_week = today - timedelta(days=today.weekday())

    def week_of(d: date) -> str:
        return (d - timedelta(days=d.weekday())).isoformat()

    weeks = _grouped(days, week_of)
    months = _grouped(days, lambda d: f"{d:%Y-%m}")
    years = _grouped(days, lambda d: f"{d:%Y}")
    if whole_years:
        current = f"{today:%Y}"
        years = [
            {
                "name": y["name"],
                "days": y["days"],
                "heat_kwh": round(y["hot_water_heat_kwh"] + y["heating_heat_kwh"], 1),
                "hot_water_heat_kwh": y["hot_water_heat_kwh"],
                "heating_heat_kwh": y["heating_heat_kwh"],
                "electricity_kwh": y["kwh"],
                "cop": y["scop"],
            }
            for y in whole_years
            if y["name"] != current  # this year's from `daily`, which stops at yesterday
        ] + [y for y in years if y["name"] == current]
    last_7 = [by_day[d] for d in (today - timedelta(days=i) for i in range(1, 8)) if d in by_day]
    points = [
        (max(0.0, base_c - temperature[d]), row["hot_water_heat_kwh"] + row["heating_heat_kwh"])
        for d, row in by_day.items()
        if d in temperature and (today - d).days <= 365
    ]
    model = fit(points)
    prediction = predict_year(today.year, by_day, temperature, model, base_c) if model else None
    return {
        "has_data": True,
        "base_c": base_c,
        "first_day": days[0]["day"],
        "yesterday": (
            {"name": yesterday.isoformat(), **_total([by_day[yesterday]])}
            if yesterday in by_day
            else None
        ),
        "last_7_days": {"name": "Last 7 days", **_total(last_7)} if last_7 else None,
        "this_week": next((w for w in weeks if w["name"] == this_week.isoformat()), None),
        "this_month": next((m for m in months if m["name"] == f"{today:%Y-%m}"), None),
        "this_year": next((y for y in years if y["name"] == f"{today:%Y}"), None),
        "days": [
            {"name": item["day"].isoformat(), **_total([item])} for item in days[-RECENT_DAYS:]
        ],
        "weeks": weeks[-RECENT_WEEKS:],
        "months": months,
        "years": years,
        "prediction": prediction,
        "fit_days_needed": MIN_FIT_DAYS,
        "fit_days": len(points),
    }
